"""Generate knxprod.h for the U3 firmware from spec.py. gen_xml.py writes the ETS XML."""
import pathlib
import spec as S

HERE = pathlib.Path(__file__).parent
OUT_H = HERE.parent / "u3" / "src" / "app" / "knxprod.h"


def header() -> str:
    L = [
        "// Generated by firmware/knxprod/gen.py from spec.py. Don't edit by hand.",
        "#pragma once",
        "",
        f"#define KNXPROD_MANUFACTURER      0x{S.MANUFACTURER:04X}",
        f"#define KNXPROD_APP_NUMBER        0x{S.APP_NUMBER:04X}",
        f"#define KNXPROD_APP_VERSION       0x{S.APP_VERSION:02X}",
        f'#define KNXPROD_ORDER_NUMBER      "{S.ORDER_NUMBER}"',
        f"#define KNXPROD_PARAM_SIZE        {S.PARAM_SIZE}",
        f"#define KNXPROD_MAX_KO            {S.MAX_KO}",
        "",
        "// Parameters: byte offset into the parameter block (big-endian), size in bits, default",
    ]
    for name, off, bits, dflt, lo, hi, text, block, enum, when in sorted(S.PARAMS, key=lambda p: p[1]):
        L.append(f"#define PARAM_{name:<22} {off:3d}  // {text}")
        L.append(f"#define PARAM_{name + '_BITS':<22} {bits:3d}")
        L.append(f"#define PARAM_{name + '_DEFAULT':<22} {dflt:5d}")
    L += ["", "// Group objects: object number, then DPT, size and flags as declared in the .knxprod"]
    for name, num, text, dpt, size, flags, block, when in S.KOS:
        L.append(f"#define KO_{name:<24} {num:3d}  // {text} {dpt} {size} {flags}")
    L.append("")
    return "\n".join(L)


if __name__ == "__main__":
    OUT_H.parent.mkdir(parents=True, exist_ok=True)
    OUT_H.write_text(header(), encoding="utf-8", newline="\n")
    print("wrote", OUT_H)
